-- Chunk 2/9 (50 outils)
BEGIN;

UPDATE tools SET long_description = E'Dotenv Vault, c''est sync et chiffrement de fichiers .env entre environnements. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Dotenv Vault : extension naturelle de dotenv. Ajoutez à ça chiffrement des fichiers .env, et synchronisation entre développeurs. Pour les usages intensifs : déploiement simplifié. Cas d''usage typique : chiffrer les fichiers .env du projet. On l''utilise aussi pour synchroniser les variables entre développeurs.\n\nÀ garder si : déjà utilisateur de dotenv ou besoin de partager des .env en équipe. À éviter si : besoin de gestion de secrets avancée ou infrastructure complexe. Point de friction : fonctionnalités limitées vs Doppler/Infisical. Gratuit — upgrade naturel si vous partagez déjà des fichiers .env par Slack.', long_description_en = E'Dotenv Vault is sync and encrypt .env files across environments. Core features are free, with paid plans for advanced use.' WHERE slug = 'dotenv-vault';
UPDATE tools SET long_description = E'HashiCorp Vault, c''est gestion de secrets et chiffrement enterprise. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue HashiCorp Vault : secrets dynamiques et rotation automatique. Ajoutez à ça chiffrement as-a-service, et politique d''accès granulaire. Pour les usages intensifs : open-source avec option enterprise. Cas d''usage typique : gérer les secrets dynamiques de base de données. On l''utilise aussi pour chiffrer des données sensibles.\n\nÀ garder si : infrastructure complexe multi-cloud ou exigences de sécurité enterprise. À éviter si : petite équipe < 5 devs ou pas d''équipe DevOps. Point de friction : complexité de déploiement et maintenance. Justifié pour les organisations avec des exigences de sécurité strictes et une équipe DevOps.', long_description_en = E'HashiCorp Vault is enterprise secret management and encryption. Core features are free, with paid plans for advanced use.' WHERE slug = 'vault';
UPDATE tools SET long_description = E'17hats, c''est cRM all-in-one pour freelances créatifs. À partir de 15€/mois.\n\nCe qui distingue 17hats : tout-en-un (CRM + facturation + contrats). Ajoutez à ça conçu pour les freelances créatifs, et automatisation des workflows clients. Pour les usages intensifs : templates de contrats et devis. Cas d''usage typique : automatiser le workflow client (devis → contrat → facture). On l''utilise aussi pour planifier des rendez-vous clients.\n\nÀ garder si : freelance créatif avec 5+ clients actifs ou besoin de consolider CRM + facturation. À éviter si : photographe (préférer Bloom ou Táve) ou besoin d''un CRM puissant. Point de friction : interface datée par rapport aux concurrents. Utile si vous jonglez entre 3+ outils pour gérer vos clients.', long_description_en = E'17hats is all-in-one CRM for creative freelancers. Starting at €15/month.' WHERE slug = '17hats';
UPDATE tools SET long_description = E'Softr, c''est plateforme pour créer des outils internes et portails sans code. À partir de 15€/mois. Particulièrement pertinent pour les fondateurs SaaS et les ai-builder.\n\nCe qui distingue Softr : spécialisé en web app builder, et interface professionnelle. Gain de temps estimé : 8h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 15€/mois.', long_description_en = E'Softr is platform for creating internal tools and portals without code. Starting at €15/month. Most relevant for SaaS founders and ai-builder.\n\nWhat sets Softr apart: specialized as a web app builder, and professional interface. Estimated time saving: 8h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to check based on usage. As soon as the tool saves you more than €15/month.' WHERE slug = 'softr';
UPDATE tools SET long_description = E'Infisical, c''est gestion de secrets open-source pour équipes dev. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Infisical : open-source et self-hostable. Ajoutez à ça interface moderne et intuitive, et intégrations CI/CD complètes. Pour les usages intensifs : sDK pour Node, Python, Go, etc. Cas d''usage typique : centraliser les secrets sans dépendance cloud. On l''utilise aussi pour intégrer la gestion de secrets dans le CI/CD.\n\nÀ garder si : besoin de gestion de secrets sans vendor lock-in ou préférence pour l''open-source. À éviter si : besoin de fonctionnalités enterprise matures ou pas de compétences DevOps. Point de friction : produit plus jeune que Vault/Doppler. Gratuit en self-hosted — excellent choix pour les équipes techniques de 2-20 devs.', long_description_en = E'Infisical is open-source secret management for dev teams. Core features are free, with paid plans for advanced use.' WHERE slug = 'infisical';
UPDATE tools SET long_description = E'LearnWorlds, c''est plateforme pour créer et vendre des cours en ligne. À partir de 25.11€/mois. Particulièrement pertinent pour les coach-formateur et les consultants B2B.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nDès que vous voulez monétiser votre expertise via des formations et avez déjà une audience. Alternative gratuite à considérer : youtube.', long_description_en = E'LearnWorlds is platform for creating and selling online courses. Starting at €25.11/month. Most relevant for coach-formateur and B2B consultants.\n\nEstimated time saving: 2h/month with regular use.\n\nAs soon as you want to monetize your expertise through courses and already have an audience. Free alternative worth considering: youtube.' WHERE slug = 'learnworlds';
