UPDATE tools SET long_description = E'Mega HR, c''est solution RH et paie pour gérer salariés et congés. À partir de 8€/mois. Particulièrement pertinent pour les consultants B2B et les daf-finance.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nDès que vous embauchez votre premier salarié (inutile pour solos). Alternative gratuite à considérer : indy.', long_description_en = E'Mega HR is hR and payroll solution to manage employees and leave. Starting at €8/month. Most relevant for B2B consultants and daf-finance.\n\nEstimated time saving: 2h/month with regular use.\n\nAs soon as you hire your first employee (not necessary for solopreneurs). Free alternative worth considering: indy.' WHERE slug = 'megahr';
UPDATE tools SET long_description = E'Kit, c''est email marketing et newsletters pour créateurs. À partir de 28.15€/mois. Particulièrement pertinent pour les ecommercant et les fondateurs SaaS.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : 500+ abonnés et monétisation active (cours, produits, services) ou besoin d''automations marketing avancées. À éviter si : newsletter mensuelle simple sans vente ou moins de 500 abonnés. Dès que vous avez 500+ abonnés et voulez monétiser. Alternative gratuite à considérer : brevo.', long_description_en = E'Kit is email marketing and newsletters for creators. Starting at €28.15/month. Most relevant for ecommercant and SaaS founders.\n\nEstimated time saving: 3h/month with regular use.\n\nKeep it if: 500+ subscribers and active monetization (courses, products, services) or need for advanced marketing automations. Skip it if: simple monthly newsletter without sales or fewer than 500 subscribers. As soon as you have 500+ subscribers and want to monetize. Free alternative worth considering: brevo.' WHERE slug = 'convertkit';
UPDATE tools SET long_description = E'Blender, c''est suite 3D complète open source : modélisation, animation, rendu, compositing. L''outil est entièrement gratuit. Particulièrement pertinent pour les motion-video et les architecte-bim.\n\nGain de temps estimé : 8h/mois pour un usage régulier.\n\nÀ garder si : modélisation 3D, animation, rendu sans budget. À éviter si : workflow Cinema 4D déjà en place — cohérence plugins. Gratuit donc toujours pertinent pour la 3D.', long_description_en = E'Blender is complete open-source 3D suite: modeling, animation, rendering, and compositing. It''s completely free. Most relevant for motion-video and architecte-bim.\n\nEstimated time saving: 8h/month with regular use.\n\nKeep it if: 3D modeling, animation, and rendering without a budget. Skip it if: workflow Cinema 4D déjà en place — cohérence plugins. Free, and therefore always relevant for 3D.' WHERE slug = 'blender';
